# ruff: noqa: E731
# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


def _gemm_configs():
    return [
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": 4},
        ),
    ]


@triton.autotune(configs=_gemm_configs(), key=["M", "N", "K"])
@triton.jit
def _gemm_bias_partial_max_kernel(
    x_ptr,
    w_ptr,
    b_ptr,
    pmax_ptr,
    M,
    N,
    K,
    stride_xm,
    stride_xk,
    stride_wk,
    stride_wn,
    stride_pm,
    stride_pn,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_pid_in_group = GROUP_SIZE_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)
    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)
    pid_n = (pid % num_pid_in_group) // group_size_m

    x_desc = tl.make_tensor_descriptor(
        base=x_ptr,
        shape=(M, K),
        strides=(stride_xm, stride_xk),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    w_desc = tl.make_tensor_descriptor(
        base=w_ptr,
        shape=(K, N),
        strides=(stride_wk, stride_wn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a = x_desc.load([pid_m * BLOCK_M, off_k])
        b = w_desc.load([off_k, pid_n * BLOCK_N])
        acc += tl.dot(a, b)

    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    bias = tl.load(b_ptr + offs_n, mask=offs_n < N, other=0.0).to(tl.float32)
    acc += bias[None, :]

    tile_max = tl.max(acc, axis=1)
    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    mask_m = offs_m < M
    tl.store(
        pmax_ptr + offs_m.to(tl.int64) * stride_pm + pid_n.to(tl.int64) * stride_pn,
        tile_max.to(pmax_ptr.dtype.element_ty),
        mask=mask_m,
    )


@triton.jit
def _reduce_max_gelu_kernel(
    pmax_ptr,
    y_ptr,
    M,
    num_n_tiles,
    stride_pm,
    stride_pn,
    stride_ym,
    BLOCK_T: tl.constexpr,
):
    row = tl.program_id(0)
    if row >= M:
        return
    row64 = row.to(tl.int64)

    row_max = -float("inf")
    for t in tl.range(0, num_n_tiles, BLOCK_T):
        offs_t = t + tl.arange(0, BLOCK_T)
        mask = offs_t < num_n_tiles
        vals = tl.load(
            pmax_ptr + row64 * stride_pm + offs_t.to(tl.int64) * stride_pn,
            mask=mask,
            other=-float("inf"),
        ).to(tl.float32)
        row_max = tl.maximum(row_max, tl.max(vals, axis=0))

    # max - mean(max) = 0, GELU(0) = 0
    tl.store(y_ptr + row64 * stride_ym, tl.zeros((), dtype=y_ptr.dtype.element_ty))


def kernel_function(x, weight_kn, bias) -> torch.Tensor:
    M, K = x.shape
    _, N = weight_kn.shape

    grid_gemm = lambda META: (
        triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),
    )

    # Estimate num_n_tiles from smallest BLOCK_N in configs (128)
    max_n_tiles = triton.cdiv(N, 128)
    pmax = torch.full((M, max_n_tiles), float("-inf"), device=x.device, dtype=x.dtype)

    _gemm_bias_partial_max_kernel[grid_gemm](
        x,
        weight_kn,
        bias,
        pmax,
        M,
        N,
        K,
        x.stride(0),
        x.stride(1),
        weight_kn.stride(0),
        weight_kn.stride(1),
        pmax.stride(0),
        pmax.stride(1),
    )

    y = torch.empty((M, 1), device=x.device, dtype=x.dtype)
    BLOCK_T = max(16, triton.next_power_of_2(max_n_tiles))
    _reduce_max_gelu_kernel[(M,)](
        pmax,
        y,
        M,
        max_n_tiles,
        pmax.stride(0),
        pmax.stride(1),
        y.stride(0),
        BLOCK_T=BLOCK_T,
        num_warps=1,
        num_stages=1,
    )
    return y


batch_size = 1024
in_features = 8192
out_features = 8192
max_dim = 1


def get_inputs():
    return [torch.rand(batch_size, in_features)]


def get_init_inputs():
    return [in_features, out_features, max_dim]


class Model(nn.Module):
    def __init__(self, in_features, out_features, max_dim):
        super().__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.max_dim = max_dim
        self._weight_kn = None

    def forward(self, x):
        if self._weight_kn is None:
            w = self.gemm.weight.data.to(dtype=x.dtype).contiguous()
            self.gemm.weight.data = w
            self.gemm.bias.data = self.gemm.bias.data.to(dtype=x.dtype).contiguous()
            self._weight_kn = w.t().contiguous()
        return kernel_function(x.contiguous(), self._weight_kn, self.gemm.bias)
